# TCP/IP Server in C

Here's a comprehensive TCP/IP server implementation with both basic and advanced examples:

## 1. **Basic TCP Server**

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <sys/socket.h>

#define PORT 8080
#define MAX_CLIENTS 5
#define BUFFER_SIZE 1024

int main() {
    int server_fd, client_fd;
    struct sockaddr_in server_addr, client_addr;
    socklen_t client_addr_len = sizeof(client_addr);
    char buffer[BUFFER_SIZE] = {0};

    // Create socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd == -1) {
        perror("Socket creation failed");
        exit(EXIT_FAILURE);
    }

    // Bind socket to port
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) == -1) {
        perror("Bind failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    // Listen for incoming connections
    if (listen(server_fd, MAX_CLIENTS) == -1) {
        perror("Listen failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    printf("Server listening on port %d...\n", PORT);

    // Accept and handle client connections
    while (1) {
        client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_addr_len);
        if (client_fd == -1) {
            perror("Accept failed");
            continue;
        }

        printf("Client connected: %s:%d\n", 
               inet_ntoa(client_addr.sin_addr), 
               ntohs(client_addr.sin_port));

        // Receive data from client
        memset(buffer, 0, BUFFER_SIZE);
        ssize_t bytes_received = recv(client_fd, buffer, BUFFER_SIZE - 1, 0);

        if (bytes_received > 0) {
            printf("Received: %s\n", buffer);

            // Send response
            const char *response = "Message received!";
            send(client_fd, response, strlen(response), 0);
        }

        close(client_fd);
    }

    close(server_fd);
    return 0;
}
```

---

## 2. **Multi-Client Server (with Threading)**

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <arpa/inet.h>
#include <sys/socket.h>

#define PORT 8080
#define MAX_CLIENTS 10
#define BUFFER_SIZE 1024

typedef struct {
    int socket_fd;
    struct sockaddr_in address;
} client_t;

void *handle_client(void *arg) {
    client_t *client = (client_t *)arg;
    char buffer[BUFFER_SIZE] = {0};

    printf("Client handler started for %s:%d\n",
           inet_ntoa(client->address.sin_addr),
           ntohs(client->address.sin_port));

    // Receive data
    while (1) {
        memset(buffer, 0, BUFFER_SIZE);
        ssize_t bytes_received = recv(client->socket_fd, buffer, BUFFER_SIZE - 1, 0);

        if (bytes_received <= 0) {
            printf("Client disconnected: %s:%d\n",
                   inet_ntoa(client->address.sin_addr),
                   ntohs(client->address.sin_port));
            break;
        }

        printf("Received from %s: %s\n", inet_ntoa(client->address.sin_addr), buffer);

        // Echo back to client
        send(client->socket_fd, buffer, bytes_received, 0);
    }

    close(client->socket_fd);
    free(client);
    pthread_exit(NULL);
}

int main() {
    int server_fd;
    struct sockaddr_in server_addr;
    pthread_t tid;

    // Create socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd == -1) {
        perror("Socket creation failed");
        exit(EXIT_FAILURE);
    }

    // Set socket options (allow reuse of port)
    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) == -1) {
        perror("setsockopt failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    // Bind socket
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) == -1) {
        perror("Bind failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    // Listen for connections
    if (listen(server_fd, MAX_CLIENTS) == -1) {
        perror("Listen failed");
        close(server_fd);
        exit(EXIT_FAILURE);
    }

    printf("Server listening on port %d...\n", PORT);

    // Accept client connections
    while (1) {
        client_t *client = malloc(sizeof(client_t));
        socklen_t client_addr_len = sizeof(client->address);

        client->socket_fd = accept(server_fd, 
                                   (struct sockaddr *)&client->address, 
                                   &client_addr_len);

        if (client->socket_fd == -1) {
            perror("Accept failed");
            free(client);
            continue;
        }

        printf("New client connected: %s:%d\n",
               inet_ntoa(client->address.sin_addr),
               ntohs(client->address.sin_port));

        // Create thread for client
        if (pthread_create(&tid, NULL, handle_client, client) != 0) {
            perror("Thread creation failed");
            close(client->socket_fd);
            free(client);
        }

        pthread_detach(tid);
    }

    close(server_fd);
    return 0;
}
```

---

## 3. **TCP Client Example**

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <sys/socket.h>

#define PORT 8080
#define SERVER_IP "127.0.0.1"
#define BUFFER_SIZE 1024

int main() {
    int sock = 0;
    struct sockaddr_in serv_addr;
    char buffer[BUFFER_SIZE] = {0};
    char message[BUFFER_SIZE];

    // Create socket
    sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("Socket creation error");
        return -1;
    }

    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(PORT);

    // Convert IP address
    if (inet_pton(AF_INET, SERVER_IP, &serv_addr.sin_addr) <= 0) {
        perror("Invalid address");
        return -1;
    }

    // Connect to server
    if (connect(sock, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        perror("Connection failed");
        return -1;
    }

    printf("Connected to server\n");
    printf("Enter message: ");
    fgets(message, BUFFER_SIZE, stdin);

    // Send message
    send(sock, message, strlen(message), 0);
    printf("Message sent\n");

    // Receive response
    memset(buffer, 0, BUFFER_SIZE);
    recv(sock, buffer, BUFFER_SIZE - 1, 0);
    printf("Received: %s\n", buffer);

    close(sock);
    return 0;
}
```

---

## **Compilation and Execution**

### For Linux/Mac:

```bash
# Compile server
gcc -o server server.c -lpthread

# Compile client
gcc -o client client.c

# Run server (Terminal 1)
./server

# Run client (Terminal 2)
./client
```

### For Windows (MinGW):

```bash
gcc -o server.exe server.c -lpthread -lws2_32
gcc -o client.exe client.c -lws2_32
```

---

## **Key Functions Explained**

| Function | Purpose |
|----------|---------|
| `socket()` | Create a socket |
| `bind()` | Bind socket to address and port |
| `listen()` | Listen for incoming connections |
| `accept()` | Accept client connection |
| `send()` | Send data to socket |
| `recv()` | Receive data from socket |
| `close()` | Close socket |
| `pthread_create()` | Create thread for multi-client handling |

---

Choose the basic version for simple applications, or the multi-threaded version for handling multiple concurrent clients!

